import {FOODS,FOOD,TOILETS,TOILET,PET,EGGS,GIFTS,fmt,toiletStats} from './data.js';
const $=s=>document.querySelector(s),esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const distanceText=n=>n<100?Number(n).toFixed(2):fmt(n);
const nav=[['food','🥯','食物'],['toilets','🚽','马桶'],['rebirth','♻️','重生'],['pets','😺','宠物'],['shop','🏪','商店'],['gifts','🎁','礼物'],['daily','📅','每日'],['world','🌍','世界'],['tasks','📋','任务']];
export class UI{
 constructor(send,thumb,callbacks){this.send=send;this.thumb=thumb;this.cb=callbacks;this.p=null;this.mode='lobby';this.modal=null;this.selectedToilet='white';this.selectedPet=null;this.signature='';this.started=false;
  $('#nav').innerHTML=nav.map(([id,art,name])=>`<button data-menu="${id}" aria-label="${name}"><span class="nav-art">${art}</span><span class="nav-name">${name}</span>${id==='gifts'?'<span class="dot" id="gift-dot">!</span>':''}</button>`).join('');
  document.addEventListener('click',e=>{const menu=e.target.closest('[data-menu]');if(menu){this.open(menu.dataset.menu);this.cb.click();return;}const a=e.target.closest('[data-action]');if(a){this.cb.click();const id=a.dataset.id,act=a.dataset.action;if(act==='roomCreate'){this.cb.roomCreate();return;}if(act==='roomJoin'){this.cb.roomJoin($('#join-code').value);return;}if(act==='roomCopy'){this.cb.roomCopy();return;}if(act==='stopAuto'){this.send({action:'toggle',key:'autoRace'});return;}if(act==='selectToilet'){this.selectedToilet=id;this.render();return;}if(act==='selectPet'){this.selectedPet=id;this.render();return;}if(act==='openEggs'){this.open('eggs');return;}if(act==='retry'){this.close(true);this.send({action:'retry'});this.cb.return();return;}if(act==='return'){this.close(true);this.send({action:'return'});this.cb.return();return;}if(act==='name'){this.send({action:'name',name:$('#player-name').value});return;}this.send({action:act,id:['egg','gift','task'].includes(act)?Number(id):id});}});
  $('#close-modal').onclick=()=>{if(this.modal==='result'){this.send({action:'return'});this.cb.return();}this.close(true);};
  $('#modal-shade').addEventListener('click',e=>{if(e.target===$('#modal-shade')&&this.modal!=='result')this.close();});
  $('#auto-eat').onclick=()=>{this.cb.unlockAudio();this.send({action:'toggle',key:'autoEat'});};$('#auto-race').onclick=()=>{this.cb.unlockAudio();this.send({action:'toggle',key:'autoRace'});};
  $('#room').onclick=()=>this.open('room');
  $('#sound').onclick=()=>{const enabled=this.cb.toggleSound();$('#sound').textContent=enabled?'♪':'♩';$('#sound').style.opacity=enabled?'1':'.5';};$('#camera-reset').onclick=()=>this.cb.resetCamera();
  $('#hatch-close').onclick=()=>{$('#hatch').classList.add('hidden');this.open('pets');};
 }
 start(){this.started=true;$('#intro').classList.add('hidden');$('#hud').classList.remove('hidden');this.cb.unlockAudio();if(this.mode==='result'&&this.result){this.lastResult=this.result.roundId;this.open('result');}this.toast('先吃几口！食物越强，每口能量越多');setTimeout(()=>{if(this.p&&!this.p.gifts.length)this.toast('🎁 迎新礼物准备好了，点击左侧礼物');},11000);setTimeout(()=>$('#hint').style.opacity='.5',25000);}
 update(p,mode,ready,result){if(this.mode==='result'&&mode!=='result'&&this.modal==='result'){this.close(true);this.cb.return();}this.p=p;this.mode=mode;this.result=result;$('#coins').textContent=fmt(p.coins);$('#power').textContent=fmt(p.power);$('#eat-gain').textContent='+'+fmt(p.gain)+' 能量';
  for(const [sel,key]of[['#auto-eat','autoEat'],['#auto-race','autoRace']]){const b=$(sel);b.classList.toggle('on',p[key]);b.setAttribute('aria-pressed',p[key]);b.querySelector('i').textContent=p[key]?'开':'关';}
  $('#game').classList.toggle('ready',ready);$('#go-race b').textContent=ready?'已报名':'去喷气';
  const sig=JSON.stringify([p.coins,p.food,p.unlocked,p.owned,p.toilet,p.levels,p.pets,p.equipped,p.rebirth,p.gifts,p.daily,p.tasks,p.style,p.autoRace,mode,result?.roundId]);if(sig!==this.signature){this.signature=sig;if(this.modal)this.render();}
  if(this.started&&mode==='result'&&result&&this.lastResult!==result.roundId){this.lastResult=result.roundId;this.open('result');if(result.newRecord)this.confetti();this.cb.result(!!result.newRecord);}
 }
 tick(){if(!this.p)return;const ready=GIFTS.some((g,i)=>this.p.playtime>=g.time&&!this.p.gifts.includes(i));$('#gift-dot').classList.toggle('hidden',!ready);for(const b of document.querySelectorAll('[data-gift-time]')){const i=Number(b.dataset.giftTime),g=GIFTS[i],left=Math.ceil(g.time-this.p.playtime);b.textContent=left>0?`${Math.floor(left/60)}:${String(left%60).padStart(2,'0')}`:'领取';b.classList.toggle('muted',left>0);}this.p.playtime+=.1;}
 toast(text,tone='info'){const n=$('#toast');n.textContent=text;n.className='visible '+tone;clearTimeout(this.toastTimer);this.toastTimer=setTimeout(()=>n.className='',3200);}
 bite(amount){const n=document.createElement('div');n.className='gain';n.textContent='💩 +'+fmt(amount);n.style.left=(72+Math.random()*3)+'%';$('#gains').append(n);setTimeout(()=>n.remove(),1100);}
 open(type){if(!this.p)return;this.modal=type;if(type==='toilets')this.selectedToilet=this.p.toilet==='none'?'white':this.p.toilet;$('#modal-shade').classList.remove('hidden');this.render();this.cb.modal(true);}
 close(force=false){if(this.modal==='result'&&!force)return;this.modal=null;$('#modal-shade').classList.add('hidden');this.cb.modal(false);}
 confetti(){for(let i=0;i<42;i++){const n=document.createElement('i');n.className='confetto';n.style.left=Math.random()*100+'%';n.style.background=['#ffe34d','#f97da2','#7ee866','#71c7ff','#b79cf8'][i%5];n.style.animationDelay=Math.random()*.6+'s';n.style.setProperty('--drift',(Math.random()-.5)*140+'px');$('#confetti').append(n);setTimeout(()=>n.remove(),4000);}}
 hatch(p,fused){this.close(true);$('#hatch-label').textContent=fused?'合成成功！':'孵化成功！';$('#hatch-name').textContent=PET[p.species].name+(p.tier?' · 金色':'');$('#hatch-image').src=this.thumb('pet',p);$('#hatch-mult').textContent='×'+p.mult.toFixed(2);$('#hatch-rarity').textContent=p.rarity+'宠物 · '+(p.tier?'更强的伙伴':'已加入你的背包');$('#hatch').classList.remove('hidden');this.cb.hatch();if(p.rarity!=='普通')this.confetti();}
 render(){const p=this.p;if(!p||!this.modal)return;const body=$('#modal-body'),scroll=body.scrollTop;let title='',content='';const im=(type,id,alt)=>`<img src="${this.thumb(type,id)}" alt="${esc(alt||'')}">`;
 if(this.modal==='room'){const info=this.cb.roomInfo();title='👥 真人联机房间';content=`<div class="room-card"><p>大厅真人同场 · 喷气独立挑战</p><b class="room-code">${esc(info.code)}</b><p>${info.local?'同一 Wi-Fi 的好友打开下面链接即可加入。外网联机需要部署公网服务器。':'好友打开下面链接即可加入同一个房间。'}</p><input class="invite-link" id="invite-link" readonly aria-label="房间邀请链接" value="${esc(info.url)}"><div class="toolbar"><button class="buy" data-action="roomCopy">复制邀请链接</button><button class="buy blue" data-action="roomCreate">新建房间</button></div></div><div class="name-input"><input id="join-code" maxlength="8" placeholder="输入房间码" aria-label="房间码" autocapitalize="characters"><button class="buy blue" data-action="roomJoin">加入</button></div><p class="modal-sub">房间最多8人。喷气时各自挑战，互不影响。</p>`+info.players.map(q=>`<div class="room-player">${im('actor',q.style,q.name)}<b>${esc(q.name)}${q.id===p.id?' · 你':''}</b><small>${!q.active?'准备进入':q.mode==='flight'?'正在喷气':q.mode==='result'?'查看成绩':q.ready?'已就绪':'在运动场'}</small></div>`).join('');}
 if(this.modal==='food'){title='🥯 运动补给';content='<p class="modal-sub">达到能量门槛就能装备。换更强的食物，每口获得更多能量！</p>'+FOODS.map(f=>{const has=p.unlocked.includes(f.id),eq=p.food===f.id;return `<div class="food-row">${im('food',f.id,f.name)}<div><h3>${f.name}</h3><span class="base">${f.base}<small>基础能量</small></span></div><button class="buy ${eq?'equipped':has?'':'locked'}" data-action="food" data-id="${f.id}">${eq?'已装备':has?'装备':'💩 '+fmt(f.need)}${has?'':'<small>解锁门槛</small>'}</button></div>`;}).join('');}
 if(this.modal==='toilets'){title='🚽 马桶';const t=TOILET[this.selectedToilet],has=p.owned.includes(t.id),eq=p.toilet===t.id,s=toiletStats({...p,toilet:t.id});content=`<p class="modal-sub">先徒步参赛赚金币，再购买马桶。大厅自由跑步，马桶只在挑战时使用。</p><div class="toolbar"><button class="buy blue ${p.toilet==='none'?'equipped':''}" data-action="unequipToilet" ${p.toilet==='none'?'disabled':''}>${p.toilet==='none'?'当前：徒步参赛':'切回徒步参赛'}</button></div><div class="detail-panel">${im('toilet',t.id,t.name)}<div><h3>${t.name} · Lv.${s.level}</h3><div class="stats"><b>×${s.speed.toFixed(2)}</b> 速度<br><b>×${s.power.toFixed(2)}</b> 力量<br><b>×${s.coins.toFixed(2)}</b> 金币</div><div class="detail-actions"><button class="buy ${eq?'equipped':''}" data-action="toilet" data-id="${t.id}">${eq?'已装备':has?'装备':'☺ '+fmt(t.cost)}</button>${has?`<button class="buy blue" data-action="upgrade" data-id="${t.id}">升级 ☺${fmt(s.upgrade)}</button>`:''}</div></div></div><div class="inventory-grid">`+TOILETS.filter(t=>t.id!=='none').map(t=>`<button class="item ${t.id===this.selectedToilet?'selected':''}" data-action="selectToilet" data-id="${t.id}">${p.toilet===t.id?'<span class="equipped-tag">已装备</span>':''}${im('toilet',t.id,t.name)}<b>${t.name}</b><span class="price">${p.owned.includes(t.id)?'已拥有':'☺ '+fmt(t.cost)}</span></button>`).join('')+'</div>';}
 if(this.modal==='pets'){title='😺 我的宠物';let pet=p.pets.find(x=>x.id===this.selectedPet);if(!pet)pet=p.pets[0];if(pet)this.selectedPet=pet.id;content=`<div class="pet-head"><span>已装备 ${p.equipped.length}/3</span><span>背包 ${p.pets.length}/50</span></div><div class="toolbar"><button class="buy" data-action="best">装备最佳</button><button class="buy blue" data-action="openEggs">去开蛋</button></div>`;if(!pet)content+='<div class="empty">🐣<br>还没有宠物<br>到蛋架开一颗蛋，伙伴会让你成长更快。</div>';else{const count=p.pets.filter(x=>x.species===pet.species&&x.tier===pet.tier&&x.mult===pet.mult).length;content+=`<div class="detail-panel">${im('pet',pet,PET[pet.species].name)}<div><h3>${PET[pet.species].name}${pet.tier?' · 金色':''}</h3><div class="stats">${pet.rarity}<br><b>×${pet.mult.toFixed(2)}</b> 力量</div><div class="detail-actions"><button class="buy" data-action="equipPet" data-id="${pet.id}">${p.equipped.includes(pet.id)?'卸下':'装备'}</button><button class="buy blue" data-action="fuse" data-id="${pet.id}">合成 ${Math.min(3,count)}/3</button><button class="buy locked" data-action="deletePet" data-id="${pet.id}">删除</button></div></div></div><div class="pet-grid">`+p.pets.map(q=>`<button class="item ${q.id===pet.id?'selected':''}" data-action="selectPet" data-id="${q.id}">${p.equipped.includes(q.id)?'<span class="equipped-tag">✓</span>':''}${im('pet',q,PET[q.species].name)}<span class="mult">×${q.mult.toFixed(2)}</span><span class="rarity">${q.rarity}${q.tier?' · 金色':''}</span></button>`).join('')+'</div>';}}
 if(this.modal==='eggs'){title='🥚 宠物蛋';content='<p class="modal-sub">每颗蛋都有不同伙伴。最多携带3只，三只相同宠物可以合成。</p><div class="egg-grid">'+EGGS.map(e=>`<div class="egg-card"><div class="egg-art">${['🥚','🐣','✨','🌈','👑'][e.id]}</div><h3>${e.name}</h3><p>普通 55% · 稀有 33% · 史诗 12%<br>倍率 ×${e.mults[0]}–${e.mults[2]}</p><button class="buy" data-action="egg" data-id="${e.id}">孵化 ☺ ${fmt(e.cost)}</button></div>`).join('')+'</div>';}
 if(this.modal==='rebirth'){title='♻️ 重生';content=`<div class="rebirth-card"><div class="rebirth-art">♻️</div><h3>重生 ${p.rebirth} 次</h3><p>当前永久力量 <b>+${p.rebirth*10}%</b><br>下一次重生再增加 <b>10%</b></p><p>当前能量归零。<br>已解锁食物、马桶、宠物继续保留。</p><button class="buy" data-action="rebirth">重生 ☺ ${fmt(p.rebirthPrice)}</button></div>`;}
 if(this.modal==='gifts'){title='🎁 在线礼物';content='<p class="modal-sub">在社区运动场玩一会儿，就能领取金币礼物。也可以先徒步参赛，再攒金币买马桶。</p><div class="gift-grid">'+GIFTS.map((g,i)=>`<div class="gift-card"><span>🎁</span><b>☺ ${fmt(g.coins)}</b><button class="buy ${p.gifts.includes(i)?'equipped':''}" data-action="gift" data-id="${i}" ${p.gifts.includes(i)?'disabled':`data-gift-time="${i}"`}>${p.gifts.includes(i)?'已领取':p.playtime>=g.time?'领取':Math.ceil(g.time-p.playtime)+'秒'}</button></div>`).join('')+'</div>';}
 if(this.modal==='daily'){title='📅 每日签到';const claimed=p.daily===new Date().toISOString().slice(0,10);content=`<div class="rebirth-card"><div class="rebirth-art">☀️</div><h3>今天也要飞得更远！</h3><p>每日到访社区，领取金币。</p><h3>☺ 250</h3><button class="buy ${claimed?'equipped':''}" data-action="daily">${claimed?'今日已签到':'领取今日奖励'}</button></div>`;}
 if(this.modal==='tasks'){title='📋 成长任务';content=[['吃10口食物',p.bites,10,75],['完成一次挑战',p.races,1,100],['拥有3只宠物',p.pets.length,3,250],['突破614.40K米',p.best,614400,5000]].map(([name,val,max,coins],i)=>`<div class="task-row"><div><h3>${name}</h3><p>${Math.min(val,max)} / ${max} · 奖励 ☺${fmt(coins)}</p></div><button class="buy ${p.tasks.includes(i)?'equipped':val<max?'muted':''}" data-action="task" data-id="${i}">${p.tasks.includes(i)?'已领取':val>=max?'领取':'进行中'}</button></div>`).join('');}
 if(this.modal==='world'){title='🌍 世界';content=`<div class="world-card"><div class="world-art">🌳</div><h3>社区运动场</h3><p>最好距离 <b>${fmt(p.best)} m</b><br>挑战次数 <b>${p.races}</b></p><p>${p.best>=614400?'🏆 你已达成614.40K米里程碑！<br>继续成长，刷新你的最远距离。':'突破自己的纪录，<br>挑战614.40K米里程碑！'}</p><div class="buy equipped">${p.best>=614400?'里程碑达成':'当前世界'}</div></div><p class="modal-sub" style="margin-top:13px">本次试玩开放完整社区运动场。后续世界暂未开放。</p>`;}
 if(this.modal==='shop'){title='🏪 商店与衣柜';content='<div class="toolbar"><button class="buy blue" data-menu="toilets">马桶商店</button><button class="buy" data-menu="eggs">宠物蛋</button></div><p class="modal-sub">换一套出场外观；你的食物、马桶和宠物保持装备。</p><div class="style-grid">'+[['suit','蓝队07号'],['bacon','橘色田径服'],['noob','向日葵套装'],['pink','莓果运动服'],['mint','薄荷队服']].map(([id,n])=>`<div class="style-card">${im('actor',id,n)}<button class="buy ${p.style===id?'equipped':''}" data-action="style" data-id="${id}">${p.style===id?'已穿戴':n}</button></div>`).join('')+`</div><div class="name-input"><input id="player-name" maxlength="12" value="${esc(p.name)}" aria-label="玩家名字"><button class="buy blue" data-action="name">改名</button></div>`;}
 if(this.modal==='result'){const r=this.result;if(!r)return;title=r.newRecord?'✨ 个人新纪录！':'💨 喷气挑战完成';const next=FOODS.find(f=>f.need>p.power);content=`<div class="result-summary"><div class="trophy">${r.newRecord?'🚀':'💨'}</div><h3>${r.newRecord?'飞得比上次更远了！':'再补给，再飞一次！'}</h3><div class="result-distance">${distanceText(r.distance)} <small>m</small></div><p>本次飞行距离</p><div class="solo-rewards"><div><small>获得金币</small><b>+${fmt(r.reward)}</b></div><div><small>最好距离</small><b>${distanceText(r.best??p.best)} m</b></div><div><small>喷气加成</small><b>+${Math.round((r.bonus||0)*100)}%</b></div></div><p>完美喷气 <b>${r.perfects||0}</b> 次 · 挑战自己的最远纪录</p>${next?`<p class="next-goal">下一补给：${esc(next.name)} · 还需 ${fmt(Math.max(0,next.need-p.power))} 能量</p>`:'<p>继续成长，刷新你的最远纪录！</p>'}</div><div class="result-footer"><button class="buy blue" data-action="return">回大厅补给</button><button class="buy" data-action="retry">再喷一次！</button></div>${p.autoRace?'<div class="result-footer"><button class="buy muted" data-action="stopAuto">停止自动挑战</button></div><p class="modal-sub">自动挑战已开，即将开始下一轮</p>':''}`;}
 if(this.modal==='leaderboard'){title='🏅 个人飞行纪录';content=`<div class="world-card"><div class="world-art">🚀</div><h3>${fmt(p.best)} m</h3><p>你的最好飞行距离<br>已完成 ${p.races} 次喷气挑战</p></div><p class="modal-sub" style="margin-top:12px">进食提升基础能量，飞行时点准金色格喷气，突破自己的纪录。</p>`;}
 $('#modal-title').textContent=title;body.innerHTML=content;body.scrollTop=scroll;this.tick();
 }
}
